<!DOCTYPE html>

<html lang="en"><head><meta charset="utf-8"/><meta content="width=device-width, initial-scale=1.0" name="viewport"/><meta content="web_blank" name="shell-type"/><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&amp;family=Plus+Jakarta+Sans:wght@600;700&amp;display=swap" rel="stylesheet"/><link href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@24,400,0,0" rel="stylesheet"/>
<link href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:wght,FILL@100..700,0..1&amp;display=swap" rel="stylesheet"/><style>@layer base{html,body{margin:0;padding:0;}body{overscroll-behavior:none;}main>:first-child{margin-top:0!important;}main>:last-child{margin-bottom:0!important;}}::-webkit-scrollbar{display:none;}</style><script src="https://cdn.tailwindcss.com"></script><script id="tailwind-config">tailwind.config={darkMode:"class",theme:{extend:{colors:{"surface-container-low":"#fff0f0","on-primary-fixed":"#40000d","background":"#fff8f7","secondary-fixed":"#ffdadb","on-secondary-fixed-variant":"#6d363b","error-container":"#ffdad6","tertiary-container":"#00864c","tertiary-fixed":"#7cfbac","on-background":"#241919","surface-tint":"#a93345","on-error":"#ffffff","on-primary-fixed-variant":"#891a2f","surface-bright":"#fff8f7","on-tertiary-container":"#f6fff4","primary":"#a63143","secondary-container":"#ffb2b7","error":"#ba1a1a","primary-fixed":"#ffdadb","outline-variant":"#debfc0","surface-container":"#ffe9e9","on-secondary-fixed":"#380c12","inverse-on-surface":"#ffedec","surface":"#fff8f7","outline":"#8a7172","on-tertiary-fixed-variant":"#00522c","on-secondary":"#ffffff","inverse-surface":"#3a2d2d","inverse-primary":"#ffb2b7","surface-container-highest":"#f3dedd","on-primary":"#ffffff","tertiary":"#006a3b","surface-dim":"#ead5d5","primary-container":"#c64959","secondary":"#894d52","surface-container-lowest":"#ffffff","secondary-fixed-dim":"#ffb2b7","on-surface-variant":"#574142","primary-fixed-dim":"#ffb2b7","on-primary-container":"#fffbff","on-surface":"#241919","on-tertiary":"#ffffff","on-tertiary-fixed":"#00210e","surface-container-high":"#f9e3e3","tertiary-fixed-dim":"#5ede92","surface-variant":"#f3dedd","on-secondary-container":"#7b4147","on-error-container":"#93000a"},borderRadius:{"DEFAULT":"0.25rem","lg":"0.5rem","xl":"0.75rem","full":"9999px"},spacing:{"margin":"1rem","space-xl":"2rem","gutter-tablet":"1.5rem","margin-tablet":"2rem","gutter":"1rem","space-md":"1rem","space-xs":"0.25rem","gutter-desktop":"2rem","space-lg":"1.5rem","space-sm":"0.5rem","margin-desktop":"3rem"},fontFamily:{"display-time-lg":["Plus Jakarta Sans"],"body-sm":["Inter"],"body-lg":["Inter"],"headline-md":["Plus Jakarta Sans"],"headline-lg":["Plus Jakarta Sans"],"label-sm":["Inter"],"label-md":["Inter"],"mono-metric":["Inter"],"body-md":["Inter"],"label-lg":["Inter"],"display-time-mobile":["Plus Jakarta Sans"],"headline-sm":["Plus Jakarta Sans"]},fontSize:{"display-time-lg":["48px",{lineHeight:"52px",letterSpacing:"-0.03em",fontWeight:"700"}],"body-sm":["12px",{lineHeight:"16px",fontWeight:"400"}],"body-lg":["16px",{lineHeight:"24px",fontWeight:"400"}],"headline-md":["22px",{lineHeight:"28px",letterSpacing:"-0.015em",fontWeight:"600"}],"headline-lg":["28px",{lineHeight:"36px",letterSpacing:"-0.02em",fontWeight:"700"}],"label-sm":["11px",{lineHeight:"14px",letterSpacing:"0.04em",fontWeight:"600"}],"label-md":["12px",{lineHeight:"16px",letterSpacing:"0.02em",fontWeight:"600"}],"mono-metric":["15px",{lineHeight:"20px",letterSpacing:"0.02em",fontWeight:"500"}],"body-md":["14px",{lineHeight:"20px",fontWeight:"400"}],"label-lg":["14px",{lineHeight:"20px",letterSpacing:"0.01em",fontWeight:"600"}],"display-time-mobile":["40px",{lineHeight:"44px",letterSpacing:"-0.025em",fontWeight:"700"}],"headline-sm":["18px",{lineHeight:"24px",letterSpacing:"-0.01em",fontWeight:"600"}]}}}}</script></head><body class="bg-background font-body-md text-on-surface antialiased min-h-screen flex items-center justify-center p-space-md"><main class="w-full flex justify-center items-center"><div class="flex flex-col w-full max-w-5xl mx-auto py-space-lg px-gutter relative">
<div class="absolute -top-16 left-1/2 -translate-x-1/2 w-96 h-96 bg-primary-container/10 rounded-full blur-3xl pointer-events-none"></div>
