<h1 class="font-headline-lg text-headline-lg text-on-surface tracking-tight mt-space-xs">TimeTrack Admin</h1>
<p class="font-body-md text-body-md text-on-surface-variant mt-1 max-w-md">Manage your TimeTrack SaaS platform and infrastructure.</p>
</div>
<div class="w-full grid grid-cols-1 lg:grid-cols-12 gap-space-lg items-start relative z-10">
<div class="lg:col-span-4 flex flex-col gap-space-md order-2 lg:order-1">
<div class="bg-surface-container-lowest p-space-lg rounded-xl shadow-md flex flex-col gap-space-md">
<div class="flex items-center justify-between">
<span class="font-label-md text-label-md text-on-surface font-semibold flex items-center gap-1.5">
<span class="material-symbols-outlined text-base text-primary">security</span>
            Telemetry &amp; Node Health
          </span>
<span class="font-label-sm text-label-sm bg-tertiary/10 text-tertiary px-space-xs py-0.5 rounded-full font-medium">Nominal</span>
</div>
<div class="space-y-space-sm">
<div class="flex justify-between items-center text-body-sm font-body-sm bg-surface-container-low p-space-sm rounded-lg">
<span class="text-on-surface-variant">Active Tenant Clusters</span>
<span class="font-mono-metric text-mono-metric text-on-surface font-semibold">1,482</span>
</div>
<div class="flex justify-between items-center text-body-sm font-body-sm bg-surface-container-low p-space-sm rounded-lg">
<span class="text-on-surface-variant">Edge Auth Latency</span>
<span class="font-mono-metric text-mono-metric text-tertiary font-semibold">18ms</span>
</div>
<div class="flex justify-between items-center text-body-sm font-body-sm bg-surface-container-low p-space-sm rounded-lg">
<span class="text-on-surface-variant">FIDO2 Hardware Gateway</span>
<span class="font-label-sm text-label-sm text-tertiary font-semibold flex items-center gap-1">
<span class="w-1.5 h-1.5 rounded-full bg-tertiary"></span> Ready
            </span>
</div>
</div>
<div class="pt-space-xs">
<div class="flex items-center justify-between text-body-sm font-body-sm text-on-surface-variant mb-1">
<span>Global Threat Level</span>
<span class="font-label-sm text-label-sm text-on-surface font-bold">DEFCON 5 (Low)</span>
</div>
<div class="w-full bg-surface-container h-2 rounded-full overflow-hidden">
<div class="bg-tertiary h-full rounded-full" style="width: 14%"></div>
</div>
</div>
</div>
<div class="bg-surface-container-low p-space-md rounded-xl shadow-sm flex items-start gap-space-sm">
<span class="material-symbols-outlined text-primary text-xl flex-shrink-0 mt-0.5">verified_user</span>
<div class="flex flex-col">
<span class="font-label-md text-label-md text-on-surface font-semibold">Hardware Keystore Connected</span>
<span class="font-body-sm text-body-sm text-on-surface-variant mt-0.5">YubiKey 5C NFC detected via WebAuthn subsystem. Slot 0x01 armed.</span>
</div>
</div>
<div class="bg-surface-container-lowest p-space-md rounded-xl shadow-sm flex items-center justify-between">
<div class="flex items-center gap-space-sm">
<span class="material-symbols-outlined text-on-surface-variant text-xl">satellite_alt</span>
<div class="flex flex-col">
<span class="font-label-sm text-label-sm text-on-surface font-semibold">Origin IP Audit</span>
<span class="font-mono-metric text-body-sm text-on-surface-variant">192.0.2.148 (Dedicated VPN)</span>
</div>
</div>
<span class="font-label-sm text-label-sm bg-surface-container px-space-xs py-0.5 rounded text-on-surface-variant">Whitelisted</span>
</div>
</div>
<div class="lg:col-span-8 flex flex-col gap-space-md order-1 lg:order-2">
<div class="bg-surface-container-lowest p-space-xl rounded-xl shadow-xl relative overflow-hidden">
<div class="absolute top-0 left-0 right-0 h-1.5 bg-gradient-to-r from-primary via-primary-container to-tertiary"></div>
<div class="bg-error-container/40 p-space-md rounded-lg mb-space-lg flex items-start gap-space-sm">
<span class="material-symbols-outlined text-error text-xl flex-shrink-0 mt-0.5" style="font-variation-settings: 'FILL' 1;">gpp_maybe</span>
<div class="flex flex-col">
<span class="font-label-md text-label-md text-on-error-container font-bold uppercase tracking-wide">Strict Zero-Tolerance Protocol</span>
<p class="font-body-sm text-body-sm text-on-error-container mt-0.5 leading-relaxed">
              Restricted Area: This administrative portal is strictly reserved for the TimeTrack platform owner and system administrators. Tenant administrators and employees are forbidden from logging in here. All anomalous connection attempts are logged with biometric telemetry and dispatched to the platform security incident responder team.
            </p>
</div>
</div>
<form class="space-y-space-lg" id="admin-login-form" onsubmit="event.preventDefault(); simulateAuth();">
<div class="space-y-space-xs">
<label class="block font-label-lg text-label-lg text-on-surface font-semibold" for="admin-email">
              Admin Email
            </label>
<div class="relative flex items-center">
<span class="material-symbols-outlined absolute left-space-md text-outline pointer-events-none text-xl">mark_email_read</span>
<input autocomplete="username" class="w-full h-12 pl-12 pr-space-md bg-surface-container-low text-on-surface font-body-md text-body-md rounded-lg outline-none focus:bg-surface-container-lowest transition-colors shadow-inner" id="admin-email" placeholder="root-identity@domain.com" required="" type="email" value="owner@timetrack.enterprise"/>
<span class="absolute right-space-md font-label-sm text-label-sm bg-surface-container text-on-surface-variant px-space-xs py-0.5 rounded">
                Tier-0 ID
              </span>
</div>
</div>
<div class="space-y-space-xs">
<div class="flex items-center justify-between">
<label class="block font-label-lg text-label-lg text-on-surface font-semibold" for="admin-password">
                Master Password
              </label>
<div class="flex items-center gap-1 font-label-sm text-label-sm text-tertiary font-medium">
<span class="material-symbols-outlined text-sm">key</span>
                Hardware Key Paired
              </div>
</div>
<div class="relative flex items-center">
<span class="material-symbols-outlined absolute left-space-md text-outline pointer-events-none text-xl">password</span>
<input autocomplete="current-password" class="w-full h-12 pl-12 pr-12 bg-surface-container-low text-on-surface font-body-md text-body-md rounded-lg outline-none focus:bg-surface-container-lowest transition-colors tracking-widest shadow-inner" id="admin-password" placeholder="Master password" required="" type="password" value="••••••••••••••••••••••••"/>
<button aria-label="Toggle password visibility" class="absolute right-space-md text-outline hover:text-on-surface transition-colors flex items-center justify-center p-1" id="toggle-pwd-btn" onclick="togglePasswordVisibility()" type="button">
<span class="material-symbols-outlined text-xl" id="pwd-icon">visibility</span>
</button>
</div>
</div>
<div class="space-y-space-xs">
<label class="block font-label-lg text-label-lg text-on-surface font-semibold">
              Two-Factor Auth / Hardware Security Key
            </label>
<div class="bg-surface-container-low p-space-md rounded-lg flex flex-col sm:flex-row items-start sm:items-center justify-between gap-space-sm">
<div class="flex items-center gap-space-sm">
<div class="w-9 h-9 rounded-lg bg-surface-container-highest flex items-center justify-center text-primary">
<span class="material-symbols-outlined text-xl">usb</span>
</div>
<div class="flex flex-col">
<span class="font-label-md text-label-md text-on-surface font-semibold flex items-center gap-1.5">
                    Hardware Security Key (FIDO2 / YubiKey)
                    <span class="w-2 h-2 rounded-full bg-tertiary inline-block"></span>
</span>
<span class="font-body-sm text-body-sm text-on-surface-variant">Tap physical sensor or enter backup TOTP below</span>
</div>
</div>
<button class="font-label-sm text-label-sm bg-surface-container-highest hover:bg-surface-container text-on-surface px-space-md py-space-xs rounded-full font-semibold transition-all flex items-center gap-1 flex-shrink-0" id="touch-fido-btn" onclick="verifyHardwareToken()" type="button">
<span class="material-symbols-outlined text-base text-primary">fingerprint</span>
                Tap to Trigger Key
              </button>
</div>
<div class="relative flex items-center mt-space-xs">
<span class="material-symbols-outlined absolute left-space-md text-outline pointer-events-none text-xl">pin</span>
<input class="w-full h-11 pl-12 pr-space-md bg-surface-container-low text-on-surface font-mono-metric text-mono-metric rounded-lg outline-none focus:bg-surface-container-lowest transition-colors shadow-inner" id="admin-totp" maxlength="6" placeholder="6-digit TOTP backup code (optional if key tapped)" type="text"/>
</div>
</div>
<div class="flex items-start gap-space-sm pt-space-xs">
<input checked="" class="w-4 h-4 rounded text-primary bg-surface-container focus:ring-0 mt-1 cursor-pointer accent-primary" id="require-reauth" type="checkbox"/>
<label class="font-body-sm text-body-sm text-on-surface cursor-pointer select-none" for="require-reauth">
              Require hardware token re-auth on sensitive operations (Database pruning, Tenant revocation, Key rotation)
            </label>
</div>
<div class="pt-space-xs">
<button class="w-full h-14 bg-primary hover:bg-primary-container active:scale-[0.99] text-on-primary font-label-lg text-label-lg rounded-full shadow-lg transition-all flex items-center justify-center gap-space-sm font-semibold tracking-wide" id="submit-btn" type="submit">
<span class="material-symbols-outlined text-xl" style="font-variation-settings: 'FILL' 1;">lock_open</span>
              Sign In to Super Admin Console
            </button>
</div>
</form>
<div class="mt-space-lg pt-space-md flex flex-col sm:flex-row items-center justify-between text-body-sm font-body-sm text-on-surface-variant gap-space-xs">
<a class="hover:text-primary transition-colors flex items-center gap-1 font-label-md text-label-md" href="javascript:void(0)" onclick="alert('Notice: Autonomous credential reset is disabled for Level-5 Super Administrators. Contact Infrastructure Security via PGP/Signal key dispatch.')">
<span class="material-symbols-outlined text-base">support_agent</span>
            Forgot Password? Contact Infrastructure Security
          </a>
<span class="font-mono-metric text-label-sm text-outline-variant uppercase">Session ID: #ROOT-8919-X2</span>
</div>
</div>
</div>
</div>
<div class="mt-space-xl text-center flex flex-col items-center gap-space-xs relative z-10 pb-space-lg">
<div class="flex flex-wrap items-center justify-center gap-x-space-md gap-y-space-xs text-on-surface-variant font-label-sm text-label-sm">
<span class="flex items-center gap-1">
<span class="material-symbols-outlined text-sm text-tertiary">lock</span>
        256-bit TLS Hardware Encrypted
      </span>
<span class="text-outline-variant">•</span>
<span class="flex items-center gap-1">
<span class="material-symbols-outlined text-sm text-tertiary">verified</span>
        SOC2 Type II In-Force
      </span>
<span class="text-outline-variant">•</span>
<span class="flex items-center gap-1">
<span class="material-symbols-outlined text-sm text-tertiary">folder_supervised</span>
        Zero-Knowledge Tenant Isolation Protocol
      </span>
</div>
<span class="font-body-sm text-body-sm text-outline">
      System build 4.19.0-core • Root Authority Verified • All rights reserved © TimeTrack Enterprise
    </span>
</div>
</div>
<script>
  function togglePasswordVisibility() {
    var pwdInput = document.getElementById('admin-password');
    var icon = document.getElementById('pwd-icon');
    if (pwdInput.type === 'password') {
      pwdInput.type = 'text';
      icon.textContent = 'visibility_off';
    } else {
      pwdInput.type = 'password';
      icon.textContent = 'visibility';
    }
  }

  function verifyHardwareToken() {
    var btn = document.getElementById('touch-fido-btn');
    var originalHTML = btn.innerHTML;
    btn.innerHTML = '<span class="material-symbols-outlined text-base animate-spin">progress_activity</span> Authenticating...';
    btn.classList.add('bg-tertiary', 'text-on-tertiary');
    
    setTimeout(function() {
      btn.innerHTML = '<span class="material-symbols-outlined text-base">check_circle</span> Key Verified (YubiKey 5C)';
      btn.classList.remove('bg-surface-container-highest');
      btn.classList.add('bg-tertiary-container', 'text-on-tertiary-container');
      var totpInput = document.getElementById('admin-totp');
      if (totpInput) {
        totpInput.placeholder = 'Hardware Key validated: Hardware PIN bypass authorized';
      }
    }, 900);
  }

  function simulateAuth() {
    var btn = document.getElementById('submit-btn');
    btn.disabled = true;
    btn.innerHTML = '<span class="material-symbols-outlined text-xl animate-spin">sync</span> Initializing Zero-Knowledge Handshake...';
    
    setTimeout(function() {
      btn.innerHTML = '<span class="material-symbols-outlined text-xl">verified_user</span> Root Credential Validated. Redirecting...';
      btn.classList.remove('bg-primary');
      btn.classList.add('bg-tertiary');
      setTimeout(function() {
        window.location.href = "{{ route('super.admin') }}";
      }, 700);
    }, 1200);
  }
</script></main></body></html>
